def odd_one_out(s):
    char_count = {}
    order = []

    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1
            order.append(char)

    result = []
    for char in reversed(order):
        if char_count[char] % 2 != 0:
            result.append(char)

    return result[::-1]
